  "common.starts_the_same_tasks_again": {"en":"Starts the same tasks again. This run stays in Past runs.","sv":"Startar samma uppgifter igen. Den här körningen finns kvar i Tidigare körningar."},
  "common.starts_up_to_n_at_once_no": {"en":"Starts {n} at a time until this Mac is read: turn on the computer reading in Settings > Agents","sv":"Startar {n} åt gången tills den här datorn är avläst: slå på datoravläsningen i Inställningar > Agenter"},
  "common.starts_up_to_n_at_once_room": {"en":"Starts up to {n} at once: room for {n} on this Mac","sv":"Startar upp till {n} samtidigt: plats för {n} på den här datorn"},
